export function isWideCodeRenderedLogo(slug: string): boolean {
  return WIDE_LOGOS.has(slug);
}

export function hasCodeRenderedLogo(slug: string): boolean {
  return Object.prototype.hasOwnProperty.call(ICON_GROUP_BY_SLUG, slug);
}

export default function InlineCatalogueLogo(props: LogoProps) {
  const Group = GROUPS[ICON_GROUP_BY_SLUG[props.slug] ?? ''];
  return Group ? <Group {...props} /> : null;
}
